PRAGMA foreign_keys=ON;
CREATE TABLE states(code TEXT PRIMARY KEY,name TEXT NOT NULL,authority TEXT NOT NULL,metadata TEXT NOT NULL);
CREATE TABLE jurisdictions(id TEXT PRIMARY KEY,state TEXT NOT NULL REFERENCES states(code),name TEXT NOT NULL,kind TEXT NOT NULL);
CREATE TABLE elections(id TEXT PRIMARY KEY,date TEXT NOT NULL,type TEXT NOT NULL,year INTEGER NOT NULL,special INTEGER NOT NULL DEFAULT 0,source_url TEXT NOT NULL,UNIQUE(date,type,special));
CREATE TABLE races(id TEXT PRIMARY KEY,election_id TEXT NOT NULL REFERENCES elections(id),state TEXT NOT NULL REFERENCES states(code),office TEXT NOT NULL,district TEXT,year INTEGER NOT NULL,data TEXT NOT NULL,source_time TEXT,retrieved_at TEXT NOT NULL);
CREATE INDEX races_year_state ON races(year,state,office);
CREATE INDEX races_election ON races(election_id);
CREATE TABLE candidates(id TEXT PRIMARY KEY,name TEXT NOT NULL,party TEXT NOT NULL);
CREATE TABLE race_candidates(race_id TEXT REFERENCES races(id),candidate_id TEXT REFERENCES candidates(id),incumbent INTEGER,PRIMARY KEY(race_id,candidate_id));
CREATE TABLE election_sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL,last_success TEXT,last_attempt TEXT,error TEXT,records INTEGER NOT NULL DEFAULT 0,interval_seconds INTEGER NOT NULL,etag TEXT,failures INTEGER NOT NULL DEFAULT 0,next_attempt TEXT);
CREATE TABLE source_coverage(source_id TEXT REFERENCES election_sources(id),state TEXT REFERENCES states(code),year INTEGER,office TEXT,status TEXT NOT NULL,PRIMARY KEY(source_id,state,year,office));
CREATE TABLE results(race_id TEXT REFERENCES races(id),source_id TEXT NOT NULL REFERENCES election_sources(id),data TEXT NOT NULL,source_time TEXT,retrieved_at TEXT NOT NULL,PRIMARY KEY(race_id,source_id));
CREATE TABLE results_snapshots(id INTEGER PRIMARY KEY,race_id TEXT NOT NULL REFERENCES races(id),source_id TEXT NOT NULL REFERENCES election_sources(id),source_time TEXT,retrieved_at TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX snapshots_retention ON results_snapshots(retrieved_at);
CREATE INDEX snapshots_race ON results_snapshots(race_id,retrieved_at);
CREATE TABLE race_calls(race_id TEXT REFERENCES races(id),source_id TEXT REFERENCES election_sources(id),candidate_id TEXT REFERENCES candidates(id),source_url TEXT NOT NULL,called_at TEXT NOT NULL,PRIMARY KEY(race_id,source_id));
CREATE TABLE polls(id TEXT PRIMARY KEY,type TEXT NOT NULL,subject TEXT NOT NULL,end_date TEXT NOT NULL,source_id TEXT REFERENCES election_sources(id),data TEXT NOT NULL);
CREATE INDEX polls_type_date ON polls(type,end_date);
CREATE TABLE poll_answers(poll_id TEXT REFERENCES polls(id),choice TEXT NOT NULL,pct REAL NOT NULL CHECK(pct>=0 AND pct<=100),PRIMARY KEY(poll_id,choice));
CREATE TABLE news_articles(id TEXT PRIMARY KEY,published TEXT NOT NULL,publisher TEXT NOT NULL,data TEXT NOT NULL);
CREATE INDEX news_date ON news_articles(published DESC);
CREATE TABLE news_race_links(article_id TEXT REFERENCES news_articles(id),race_id TEXT REFERENCES races(id),method TEXT NOT NULL,PRIMARY KEY(article_id,race_id));
CREATE TABLE sync_runs(id TEXT PRIMARY KEY,source_id TEXT REFERENCES election_sources(id),started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,records INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE INDEX sync_retention ON sync_runs(started_at);
CREATE TABLE historical_results(race_id TEXT PRIMARY KEY REFERENCES races(id),year INTEGER NOT NULL,geography_version TEXT,data TEXT NOT NULL);
CREATE INDEX historical_year ON historical_results(year);
CREATE TABLE dashboard_cache(key TEXT PRIMARY KEY,data TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE operations(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
